INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-046-2', 'p0212', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '程普請擊昭，策曰：「許昭有義於舊君，有誠於故友，此丈夫之志也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-046-3', 'p0212', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣以十一日平旦部所領江夏太守行建威中郎將周瑜、領桂陽太守行征虜中郎將呂範、領零陵太守行蕩寇中郎將程普、行奉業校尉孫權、行先登校尉韓當、行武鋒校尉黃蓋等同時俱進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-047-4', 'p0212', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '待張昭以師傅之禮，而周瑜、程普、呂範等為將率。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-047-5', 'p0212', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '還過豫章，使呂範平鄱陽、會稽，程普討樂安，太史慈領海昏，韓當、周泰、呂蒙等為劇縣令長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-047-6', 'p0212', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '備進住夏口，使諸葛亮詣權，權遣周瑜、程普等行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-048-7', 'p0212', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-051-8', 'p0212', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '遷都護征虜將軍，代程普督夏口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-051-9', 'p0212', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '昔周瑜、程普為左右部督，共攻江陵，雖事決於瑜，普自恃乆將，且俱是督，遂共不睦，幾敗國事，此目前之戒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-052-10', 'p0212', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」隲於是條于時事業在荊州界者，諸葛瑾、陸遜、朱然、程普、潘濬、裴玄、夏侯承、衞旌、李肅、吳書曰：肅字偉恭，南陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-054-11', 'p0212', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '時劉備為曹公所破，欲引南渡江，與魯肅遇於當陽，遂共圖計，因進住夏口，遣諸葛亮詣權，權遂遣瑜及程普等與備并力逆曹公，遇於赤壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-054-12', 'p0212', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '瑜與程普又進南郡，與仁相對，各隔大江。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-054-13', 'p0212', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '後著令曰：「故將軍周瑜、程普，其有人客，皆不得問。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-054-14', 'p0212', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '性度恢廓，大率為得人，惟與程普不睦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-054-15', 'p0212', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '是歲，又與周瑜、程普等西破曹公於烏林，圍曹仁於南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-055-16', 'p0212', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '程普字德謀，右北平土垠人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-055-17', 'p0212', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後與周瑜、程普拒曹公於赤壁，攻曹仁於南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0213-a04-046-0', 'p0213', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣以十一日平旦部所領江夏太守行建威中郎將周瑜、領桂陽太守行征虜中郎將呂範、領零陵太守行蕩寇中郎將程普、行奉業校尉孫權、行先登校尉韓當、行武鋒校尉黃蓋等同時俱進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0213-a04-048-1', 'p0213', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0213-a04-049-2', 'p0213', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '策從騎十三，皆韓當、宋謙、黃蓋輩也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0213-a04-051-3', 'p0213', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '黃蓋及兄瑜卒，又并其軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0213-a04-053-4', 'p0213', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '及臣所見，南海黃蓋為日南太守，下車以供設不豐，檛殺主簿，仍見驅逐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0213-a04-054-5', 'p0213', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '瑜部將黃蓋曰：「今寇衆我寡，難與持乆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0213-a04-055-6', 'p0213', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '黃蓋字公覆，零陵泉陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-018-0', 'p0214', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '張遼之討陳蘭，霸別遣至皖，討吳將韓當，使權不得救蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-046-1', 'p0214', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣以十一日平旦部所領江夏太守行建威中郎將周瑜、領桂陽太守行征虜中郎將呂範、領零陵太守行蕩寇中郎將程普、行奉業校尉孫權、行先登校尉韓當、行武鋒校尉黃蓋等同時俱進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-046-2', 'p0214', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」荅云：「是韓當兵，在此射鹿耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-046-3', 'p0214', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '又江表傳說策悉識韓當軍士，疑此為詐，便射殺一人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-047-4', 'p0214', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '還過豫章，使呂範平鄱陽、會稽，程普討樂安，太史慈領海昏，韓當、周泰、呂蒙等為劇縣令長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-047-5', 'p0214', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '閏月，韓當子綜以其衆降魏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-048-6', 'p0214', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-049-7', 'p0214', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '策從騎十三，皆韓當、宋謙、黃蓋輩也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-055-8', 'p0214', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '蓋自彊以一聲呼韓當，當聞之，曰：「此公覆聲也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-055-9', 'p0214', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '韓當字義公，遼西令支人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-058-10', 'p0214', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '黃武元年，劉備率大衆來向西界，權命遜為大都督、假節，督朱然、潘璋、宋謙、韓當、徐盛、鮮于丹、孫桓等五萬人拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-048-0', 'p0215', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-054-1', 'p0215', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '江表傳曰：初，權謂蒙及蔣欽曰：「卿今並當塗掌事，宜學問以自開益。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-054-2', 'p0215', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '權常歎曰：「人長而進益，如呂蒙、蔣欽，蓋不可及也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-054-3', 'p0215', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '初，魯肅等以為曹公尚存，禍難始搆，宜相輔協，與之同仇，不可失也，蒙乃密陳計策曰：「令征虜守南郡，潘璋住白帝，蔣欽將游兵萬人，循江上下，應敵所在，蒙為國家前據襄陽，如此，何憂於操，何賴於羽？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-055-4', 'p0215', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '蔣欽字公弈，九江壽春人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-055-5', 'p0215', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '與蔣欽隨孫策為左右，服事恭敬，數戰有功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-055-6', 'p0215', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '鄱陽賊彭虎等衆數萬人，襲與凌統、步隲、蔣欽各別分討。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-055-7', 'p0215', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '建安二十年，從攻合肥，會疫疾，軍旅皆已引出，唯車下虎士千餘人，并呂蒙、蔣欽、凌統及寧，從權逍遙津北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-060-8', 'p0215', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '會稽東冶五縣賊呂合、秦狼等為亂，權以岱為督軍校尉，與將軍蔣欽等將兵討之，遂禽合、狼，五縣平定，拜昭信中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0216-a04-047-0', 'p0216', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '還過豫章，使呂範平鄱陽、會稽，程普討樂安，太史慈領海昏，韓當、周泰、呂蒙等為劇縣令長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0216-a04-047-1', 'p0216', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '近得守將周泰、全琮等白事，過月六日，有馬步七百，徑到橫江，又督將馬和復將四百人進到居巢，琮等聞有兵馬渡江，視之，為兵馬所擊，臨時交鋒，大相殺傷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0216-a04-048-2', 'p0216', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0216-a04-055-3', 'p0216', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '周泰字幼平，九江下蔡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0216-a04-055-4', 'p0216', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫盛曰：觀孫權之養士也，傾心竭思，以求其死力，泣周泰之夷，殉陳武之妾，請呂蒙之命，育凌統之孤，卑曲苦志，如此之勤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0217-a04-001-0', 'p0217', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖上書陳武等正直而見陷害，姦邪盈朝，善人壅塞，其言甚切；靈帝不能用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0217-a04-039-1', 'p0217', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '陳武與表俱至偏將軍，以位不相過故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0217-a04-048-2', 'p0217', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0217-a04-055-3', 'p0217', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '陳武字子烈，廬江松滋人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0217-a04-055-4', 'p0217', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫盛曰：觀孫權之養士也，傾心竭思，以求其死力，泣周泰之夷，殉陳武之妾，請呂蒙之命，育凌統之孤，卑曲苦志，如此之勤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0217-a04-055-5', 'p0217', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '合肥之役，張遼奄至，諸將不備，陳武鬬死，宋謙、徐盛皆披走，璋身次在後，便馳進，橫馬斬謙、盛兵走者二人，兵皆還戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0218-a04-047-0', 'p0218', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十三年春，權復征黃祖，祖先遣舟兵拒軍，都尉呂蒙破其前鋒，而淩統、董襲等盡銳攻之，遂屠其城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0218-a04-048-1', 'p0218', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0218-a04-055-2', 'p0218', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '董襲字元代，會稽餘姚人，長八尺，武力過人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-031-0', 'p0219', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '荊州別駕劉闔，璋將沈彌、婁發、甘寧反，擊璋不勝，走入荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-037-1', 'p0219', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '今荊州道通，衆數十倍，加孫車騎遣弟及李異、甘寧等為其後繼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-047-2', 'p0219', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '時甘寧在夷陵，為仁黨所圍，用呂蒙計，留凌統以拒仁，以其半救寧，軍以勝反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-047-3', 'p0219', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '兵皆就路，權與凌統、甘寧等在津北為魏將張遼所襲，統等以死扞權，權乘駿馬越津橋得去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-048-4', 'p0219', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-051-5', 'p0219', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '嘗以小故與甘寧忿爭，或以諫寧，寧曰：「臣子一例，征虜雖公子，何可專行侮人邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-054-6', 'p0219', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '先是，益州牧劉璋綱維頹弛，周瑜、甘寧並勸權取蜀，權以咨備，備內欲自規，乃偽報曰：「備與璋託為宗室，兾憑英靈，以匡漢朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-054-7', 'p0219', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '瑜使甘寧前據夷陵，曹仁分衆攻寧，寧困急，使使請救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-054-8', 'p0219', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '蒙乃薦甘寧為升城督，督攻在前，蒙以精銳繼之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-054-9', 'p0219', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '甘寧麤暴好殺，旣常失蒙意，又時違權令，權怒之，蒙輒陳請：「天下未定，鬬將如寧難得，宜容忍之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-055-10', 'p0219', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '甘寧字興霸，巴郡臨江人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-055-11', 'p0219', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '寧引白削置膝上，呵謂之曰：「卿見知於至尊，孰與甘寧？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-055-12', 'p0219', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '甘寧尚不惜死，卿何以獨惜死乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-055-13', 'p0219', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '蒙母徒跣出諫蒙曰：「至尊待汝如骨肉，屬汝以大事，何有以私怒而欲攻殺甘寧？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-055-14', 'p0219', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '少以驍勇為小將，屬甘寧、陸遜、潘璋等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0220-a04-047-0', 'p0220', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十三年春，權復征黃祖，祖先遣舟兵拒軍，都尉呂蒙破其前鋒，而淩統、董襲等盡銳攻之，遂屠其城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0220-a04-048-1', 'p0220', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0220-a04-048-2', 'p0220', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '高張公之德而省游田之娛，賢諸葛之言而割情欲之歡，感陸公之規而除刑政之煩，奇劉基之議而作三爵之誓，屏氣跼蹐以伺子明之疾，分滋損甘以育淩統之孤，登壇慷慨歸魯肅之功，削投惡言信子瑜之節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0220-a04-054-3', 'p0220', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '師還，遂征合肥，旣徹兵，為張遼等所襲，蒙與淩統以死扞衞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0220-a04-064-4', 'p0220', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '淩統聞之，請與相見，甚奇之，乃表薦贊，遂被試用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-047-0', 'p0221', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '將軍全琮、徐盛追斬魏將尹盧，殺獲數百。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-055-1', 'p0221', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '蕪湖令徐盛收欽屯吏，表斬之，權以欽在遠不許，盛由是自嫌於欽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-055-2', 'p0221', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '時朱然、徐盛等皆在所部，並不伏也，權特為案行至濡須鄔，因會諸將，大為酣樂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-055-3', 'p0221', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '徐盛字文嚮，琅邪莒人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-055-4', 'p0221', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '合肥之役，張遼奄至，諸將不備，陳武鬬死，宋謙、徐盛皆披走，璋身次在後，便馳進，橫馬斬謙、盛兵走者二人，兵皆還戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-056-5', 'p0221', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '曹休、張遼、臧霸等來伐，範督徐盛、全琮、孫韶等，以舟師拒休等於洞口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-058-6', 'p0221', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '黃武元年，劉備率大衆來向西界，權命遜為大都督、假節，督朱然、潘璋、宋謙、韓當、徐盛、鮮于丹、孫桓等五萬人拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-058-7', 'p0221', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '又備旣住白帝，徐盛、潘璋、宋謙等各競表言備必可禽，乞復攻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-060-8', 'p0221', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '時城中出戰，徐盛被創失矛，齊引兵拒擊，得盛所失。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-036-0', 'p0222', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '臣松之桉吳書：孫權遣將潘璋逆斷羽走路，羽至即斬，且臨沮去江陵二三百里，豈容不時殺羽，方議其生死乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-047-1', 'p0222', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '蒙使人誘普，普降，盡得三郡將守，因引軍還，與孫皎、潘璋并魯肅兵並進，拒羽於益陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-047-2', 'p0222', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權先使朱然、潘璋斷其徑路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-047-3', 'p0222', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權以陸遜為督，督朱然、潘璋等以拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-047-4', 'p0222', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權遣呂範等督五軍，以舟軍拒休等，諸葛瑾、潘璋、楊粲救南郡，朱桓以濡須督拒仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-048-5', 'p0222', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-052-6', 'p0222', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '及春水生，潘璋等作水城於上流，瑾進攻浮橋，真等退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-054-7', 'p0222', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '初，魯肅等以為曹公尚存，禍難始搆，宜相輔協，與之同仇，不可失也，蒙乃密陳計策曰：「令征虜守南郡，潘璋住白帝，蔣欽將游兵萬人，循江上下，應敵所在，蒙為國家前據襄陽，如此，何憂於操，何賴於羽？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-054-8', 'p0222', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '權使朱然、潘璋斷其徑路，即父子俱獲，荊州遂定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-055-9', 'p0222', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '潘璋字文珪，東郡發干人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-055-10', 'p0222', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '少以驍勇為小將，屬甘寧、陸遜、潘璋等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-055-11', 'p0222', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '以潘璋之不脩，權能忘過記功，其保據東南，宜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-056-12', 'p0222', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '建安二十四年，從討關羽，別與潘璋到臨沮禽羽，遷昭武將軍，封西安鄉侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-056-13', 'p0222', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '權遣潘璋、楊粲等解，而圍不解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-056-14', 'p0222', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '六年，權自率衆攻石陽，及至旋師，潘璋斷後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-058-15', 'p0222', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '黃武元年，劉備率大衆來向西界，權命遜為大都督、假節，督朱然、潘璋、宋謙、韓當、徐盛、鮮于丹、孫桓等五萬人拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-058-16', 'p0222', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '又備旣住白帝，徐盛、潘璋、宋謙等各競表言備必可禽，乞復攻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-060-17', 'p0222', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '嘉禾二年，權令岱領潘璋士衆，屯陸口，後徙蒲圻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-060-18', 'p0222', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂範、孫韶等入淮，全琮、朱桓趨合肥，諸葛瑾、步隲、朱然到襄陽，陸議、潘璋等討梅敷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-063-19', 'p0222', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '」權使潘璋邀其徑路，覘候者還，白羽已去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-0', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '冬十月丁未，遣孫憲及丁奉、施寬等以舟兵逆據於江都，遣將軍劉丞督步騎攻胤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-1', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '秋七月，綝率衆救壽春，次于鑊里，朱異至自夏口，綝使異為前部督，與丁奉等將介士五萬解圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-2', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '甲申，使大將軍丁奉督諸軍向魏壽春，將軍留平別詣施績於南郡，議兵所向，將軍丁封、孫異如沔中，皆救蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-3', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '元興元年八月，以上大將軍施績、大將軍丁奉為左右大司馬，張布為驃騎將軍，加侍中，諸增位班賞，一皆如舊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-4', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '秋九月，皓出東關，丁奉至合肥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-5', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '右大司馬丁奉、司空孟仁卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-6', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '江表傳曰：初皓游華里，彧與丁奉、留平密謀曰：「此行不急，若至華里不歸，社稷事重，不得不自還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-7', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '大司馬陸公以文武熈朝，左丞相陸凱以謇諤盡規，而施績、范慎以威重顯，丁奉、鍾離斐以武毅稱，孟宗、丁固之徒為公卿，樓玄、賀劭之屬掌機事，元首雖病，股肱猶良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-055-8', 'p0223', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '丁奉字承淵，廬江安豐人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-055-9', 'p0223', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫休即位，與張布謀，欲誅孫綝，布曰：「丁奉雖不能吏書，而計略過人，能斷大事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-060-10', 'p0223', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '東關之役，緒與丁奉建議引兵先出，以破魏軍，封一子亭侯，年四十四卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-061-11', 'p0223', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '或曰寶鼎元年十二月，凱與大司馬丁奉、御史大夫丁固謀，因皓謁廟，欲廢皓立孫休子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-061-12', 'p0223', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '吳錄曰：舊拜廟，選兼大將軍領三千兵為衞，凱欲因此兵圖之，令選曹白用丁奉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-061-13', 'p0223', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '平素與丁奉有隙，禕未及得宣凱旨，平語禕曰：「聞野豬入丁奉營，此凶徵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-064-14', 'p0223', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '恪遣將軍留贊、呂據、唐咨、丁奉為前部。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-064-15', 'p0223', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '綝於是大發卒出屯鑊里，復遣異率將軍丁奉、黎斐等五萬人攻魏，留輜重於都陸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-064-16', 'p0223', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '亮內嫌綝，乃推魯育見殺本末，責怒虎林督朱熊、熊弟外部督朱損不匡正孫峻，乃令丁奉殺熊於虎林，殺損於建業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-064-17', 'p0223', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '休密問張布，布與丁奉謀於會殺綝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a05-003-18', 'p0223', 'jinshu', 'a05-003', '《晉書·卷三》', '十一月，吳將丁奉等出芍陂，安東將軍汝陰王駿與義陽王望擊走之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a05-003-19', 'p0223', 'jinshu', 'a05-003', '《晉書·卷三》', '吳將丁奉入渦口，揚州刺史牽弘擊走之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a05-037-20', 'p0223', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '俄而吳將丁奉寇芍陂，望又率諸軍以赴之，未至而奉退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-003-0', 'p0224', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '孫權遣將朱然等二萬人圍江夏郡，荊州刺史胡質等擊之，然退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-004-1', 'p0224', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '夏五月，吳將朱然等圍襄陽之樊城，太傅司馬宣王率衆拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-004-2', 'p0224', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '干寶晉紀曰：吳將全琮寇芍陂，朱然、孫倫五萬人圍樊城，諸葛瑾、步隲寇柤中；琮已破走而樊圍急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-004-3', 'p0224', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '習鑿齒漢晉春秋曰：是年，吳將朱然入柤中，斬獲數千；柤中民吏萬餘家渡沔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-014-4', 'p0224', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '大司馬曹休帥軍向皖，濟表以為「深入虜地，與權精兵對，而朱然等在上流，乘休後，臣未見其利也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-015-5', 'p0224', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '正始二年，朱然圍樊城，城中守將乙脩等求救甚急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-022-6', 'p0224', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」亮又出斜谷；征南上：「朱然等軍已過荊城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-023-7', 'p0224', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時吳使朱然、諸葛瑾攻圍樊城，遣船兵於峴山東斫材，牂牁人兵作食，有先熟者呼後熟者，言：「共食來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-025-8', 'p0224', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '上軍大將軍曹真征朱然于江陵，毗行軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-027-9', 'p0224', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '吳大將朱然圍樊城，質輕軍赴之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-027-10', 'p0224', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '基曰：「昔孫權再至合肥，一至江夏，其後全琮出廬江，朱然寇襄陽，皆無功而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-11', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權先使朱然、潘璋斷其徑路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-12', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權以陸遜為督，督朱然、潘璋等以拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-13', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '禮還，復有詔責數諸葛瑾、步隲、朱然、呂岱等曰：「袁禮還，云與子瑜、子山、義封、定公相見，並以時事當有所先後，各自以不掌民事，不肯便有所陳，悉推之伯言、承明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-14', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '車騎將軍朱然圍樊，大將軍諸葛瑾取柤中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-15', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '陛下身自御戎，取亂侮亡，宜滌荊、揚之地，舉彊羸之數，使彊者執戟，羸者轉運，西命益州軍于隴右，授諸葛瑾、朱然大衆指事襄陽，陸遜、朱桓別征壽春，大駕入淮陽，歷青、徐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-16', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '是歲，步隲、朱然等各上疏云：「自蜀還者，咸言背盟與魏交通，多作舟舩，繕治城郭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-17', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '九年春二月，車騎將軍朱然征魏柤中，斬獲千餘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-18', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，以驃騎步隲為丞相，車騎朱然為左大司馬，衞將軍全琮為右大司馬，鎮南呂岱為上大將軍，威北將軍諸葛恪為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-19', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十一年春正月，朱然城江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-20', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十二年春三月，左大司馬朱然卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-21', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '及權繼其業，有張子布以為腹心，有陸議、諸葛瑾、步隲以為股肱，有呂範、朱然以為爪牙，分任受職，乘閒伺隙，兵不妄動，故戰少敗而江南安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-048-22', 'p0224', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-052-23', 'p0224', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '吳錄曰：曹真、夏侯尚等圍朱然於江陵，又分據中州，瑾以大兵為之救援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-052-24', 'p0224', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」隲於是條于時事業在荊州界者，諸葛瑾、陸遜、朱然、程普、潘濬、裴玄、夏侯承、衞旌、李肅、吳書曰：肅字偉恭，南陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-054-25', 'p0224', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」瑾、隲表比上，朱然及全琮亦俱陳乞，權乃許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-054-26', 'p0224', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '權使朱然、潘璋斷其徑路，即父子俱獲，荊州遂定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-055-27', 'p0224', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '宜都之役，與陸遜、朱然等共攻蜀軍於涿鄉，大破之，徙威烈將軍，封都亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-055-28', 'p0224', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '時朱然、徐盛等皆在所部，並不伏也，權特為案行至濡須鄔，因會諸將，大為酣樂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-055-29', 'p0224', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權征關羽，璋與朱然斷羽走道，到臨沮，住夾石。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-056-30', 'p0224', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '朱然字義封，治姊子也，本姓施氏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-056-31', 'p0224', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '」蒙對曰：「朱然膽守有餘，愚以為可任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-056-32', 'p0224', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '吳志說赤烏五年，於魏為正始三年，魏將蒲忠與朱然戰，忠不利，質等皆退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-056-33', 'p0224', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '朱然攻樊，據與朱異破城外圍，還拜偏將軍，入補馬閑右部督，遷越騎校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-056-34', 'p0224', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '赤烏四年，隨朱然攻魏樊城，建計破其外圍，還拜偏將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-056-35', 'p0224', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '評曰：朱治、呂範以舊臣任用，朱然、朱桓以勇烈著聞，呂據、朱異、施績咸有將領之才，克紹堂構。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-058-36', 'p0224', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '黃武元年，劉備率大衆來向西界，權命遜為大都督、假節，督朱然、潘璋、宋謙、韓當、徐盛、鮮于丹、孫桓等五萬人拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-058-37', 'p0224', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '權以問遜，遜與朱然、駱統以為曹丕大合士衆，外託助國討備，內實有姦心，謹決計輒還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-059-38', 'p0224', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-060-39', 'p0224', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂範、孫韶等入淮，全琮、朱桓趨合肥，諸葛瑾、步隲、朱然到襄陽，陸議、潘璋等討梅敷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a05-001-40', 'p0224', 'jinshu', 'a05-001', '《晉書·卷一》', '二年夏五月，吳將全琮寇芍陂，朱然、孫倫圍樊城，諸葛瑾、步騭掠柤中，帝請自討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a05-013-41', 'p0224', 'jinshu', 'a05-013', '《晉書·卷十三》', '九月，吳將朱然圍江夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-047-0', 'p0225', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權遣呂範等督五軍，以舟軍拒休等，諸葛瑾、潘璋、楊粲救南郡，朱桓以濡須督拒仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-047-1', 'p0225', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '仁子泰因引軍急攻朱桓，桓兵拒之，遣將軍嚴圭等擊破彫等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-047-2', 'p0225', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '陛下身自御戎，取亂侮亡，宜滌荊、揚之地，舉彊羸之數，使彊者執戟，羸者轉運，西命益州軍于隴右，授諸葛瑾、朱然大衆指事襄陽，陸遜、朱桓別征壽春，大駕入淮陽，歷青、徐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-048-3', 'p0225', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-056-4', 'p0225', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '朱桓字休穆，吳郡吳人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-056-5', 'p0225', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '評曰：朱治、呂範以舊臣任用，朱然、朱桓以勇烈著聞，呂據、朱異、施績咸有將領之才，克紹堂構。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-058-6', 'p0225', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '遜自為中部，令朱桓、全琮為左右翼，三道俱進，果衝休伏兵，因驅走之，追亡逐北，徑至夾石，斬獲萬餘，牛馬騾驢車乘萬兩，軍資器械略盡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-060-7', 'p0225', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂範、孫韶等入淮，全琮、朱桓趨合肥，諸葛瑾、步隲、朱然到襄陽，陸議、潘璋等討梅敷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-002-0', 'p0226', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '今征東諸軍與權黨呂範等水戰，則斬首四萬，獲船萬艘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-009-1', 'p0226', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '帝征孫權，以休為征東大將軍，假黃鉞，督張遼等及諸州郡二十餘軍，擊權大將呂範等於洞浦，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-015-2', 'p0226', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '黃初中，與諸將並征吳，破呂範於洞浦，進封陽里亭侯，加建威將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-017-3', 'p0226', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '」是歲，遼與諸將破權將呂範。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-018-4', 'p0226', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與曹休討吳賊，破呂範於洞浦，徵為執金吾，位特進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-028-5', 'p0226', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '臨江，夜大風，吳將呂範等船漂至北岸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-046-6', 'p0226', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '策舅吳景，時為丹楊太守，策乃載母徙曲阿，與呂範、孫河俱就景，因緣召募得數百人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-046-7', 'p0226', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '策覺之，遣呂範、徐逸攻瑀於海西，大破瑀，獲其吏士妻子四千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-046-8', 'p0226', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣以十一日平旦部所領江夏太守行建威中郎將周瑜、領桂陽太守行征虜中郎將呂範、領零陵太守行蕩寇中郎將程普、行奉業校尉孫權、行先登校尉韓當、行武鋒校尉黃蓋等同時俱進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-047-9', 'p0226', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '待張昭以師傅之禮，而周瑜、程普、呂範等為將率。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-047-10', 'p0226', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '還過豫章，使呂範平鄱陽、會稽，程普討樂安，太史慈領海昏，韓當、周泰、呂蒙等為劇縣令長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-047-11', 'p0226', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權遣呂範等督五軍，以舟軍拒休等，諸葛瑾、潘璋、楊粲救南郡，朱桓以濡須督拒仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-047-12', 'p0226', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '及權繼其業，有張子布以為腹心，有陸議、諸葛瑾、步隲以為股肱，有呂範、朱然以為爪牙，分任受職，乘閒伺隙，兵不妄動，故戰少敗而江南安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-048-13', 'p0226', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-050-14', 'p0226', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫策與孫河、呂範依景，合衆共討涇縣山賊祖郎，郎敗走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-051-15', 'p0226', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '江表傳曰：曹休出洞口，呂範率軍禦之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-051-16', 'p0226', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '」而江表傳云呂範在洞口，匡為定武中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-052-17', 'p0226', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」後有呂範、諸葛恪為說隲所言，云：「每讀步隲表，輒失笑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-054-18', 'p0226', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '漢晉春秋曰：呂範勸留備，肅曰：「不可。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-055-19', 'p0226', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '曹休出洞口，盛與呂範、全琮渡江拒守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-056-20', 'p0226', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '呂範字子衡，汝南細陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-056-21', 'p0226', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '評曰：朱治、呂範以舊臣任用，朱然、朱桓以勇烈著聞，呂據、朱異、施績咸有將領之才，克紹堂構。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-057-22', 'p0226', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '黃武元年，與呂範、賀齊等俱以舟師拒魏將曹休於洞口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-058-23', 'p0226', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '吳書曰：權嘉遜功德，欲殊顯之，雖為上將軍列侯，猶欲令歷本州舉命，乃使揚州牧呂範就辟別駕從事，舉茂才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-060-24', 'p0226', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '黃初元年，魏以舟軍大出洞口，權使呂範督諸將拒之，軍營相望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-060-25', 'p0226', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂範、孫韶等入淮，全琮、朱桓趨合肥，諸葛瑾、步隲、朱然到襄陽，陸議、潘璋等討梅敷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0227-a04-046-0', 'p0227', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '盡更置長吏，策自領會稽太守，復以吳景為丹楊太守，以孫賁為豫章太守；分豫章為廬陵郡，以賁弟輔為廬陵太守，丹楊朱治為吳郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0227-a04-051-1', 'p0227', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '太守朱治舉孝廉，司空辟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0227-a04-052-2', 'p0227', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '吳郡太守朱治，權舉將也，權曾有以望之，而素加敬，難自詰讓，忿忿不解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0227-a04-056-3', 'p0227', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '朱治字君理，丹楊故鄣人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0227-a04-056-4', 'p0227', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '評曰：朱治、呂範以舊臣任用，朱然、朱桓以勇烈著聞，呂據、朱異、施績咸有將領之才，克紹堂構。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0227-a04-057-5', 'p0227', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '國家之於曁豔，不內之忌族，猶等之平民，是故先見用於朱治，次見舉於衆人，中見任於明朝，亦見交於義也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-047-0', 'p0228', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '丙寅，驃騎將軍朱據領丞相，燎鵲以祭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-048-1', 'p0228', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '」初為驃騎將軍朱據軍吏，將母在營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-050-2', 'p0228', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '生二女，長曰魯班，字大虎，前配周瑜子循，後配全琮；少曰魯育，字小虎，前配朱據，後配劉纂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-050-3', 'p0228', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫休朱夫人，朱據女，休姊公主所生也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-052-4', 'p0228', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '權末年，嫡庶不分，悌數與驃騎將軍朱據共陳禍福，言辭切直，朝廷憚之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-056-5', 'p0228', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '異字季文，以父任除郎，文士傳曰：張惇子純與張儼及異俱童少，往見驃騎將軍朱據。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-057-6', 'p0228', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '朱據字子範，吳郡吳人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-057-7', 'p0228', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '數月，典軍吏劉助覺，言王遂所取，權大感寤，曰：「朱據見枉，況吏民乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-057-8', 'p0228', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '吾粲、朱據遭罹屯蹇，以正喪身，悲夫！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-059-9', 'p0228', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-059-10', 'p0228', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-059-11', 'p0228', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '於是驃騎將軍朱據、尚書僕射屈晃率諸將吏泥頭自縛，連日詣闕請和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-061-12', 'p0228', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '時校事呂壹操弄威柄，奏桉丞相顧雍、左將軍朱據等，皆見禁止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-062-13', 'p0228', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '左將軍朱據、廷尉郝普稱蕃有王佐之才，普尤與之親善，常怨歎其屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-064-14', 'p0228', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '朱據先帝舊臣，子男熊、損皆承父之基，以忠義自立，昔殺小主，自是大主所創，帝不復精其本末，便殺熊、損，諫不見用，諸下莫不側息。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-004-0', 'p0229', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '干寶晉紀曰：吳將全琮寇芍陂，朱然、孫倫五萬人圍樊城，諸葛瑾、步隲寇柤中；琮已破走而樊圍急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-024-1', 'p0229', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '吳大將全琮帥數萬衆來侵寇，時州兵休使，在者無幾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-027-2', 'p0229', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '基曰：「昔孫權再至合肥，一至江夏，其後全琮出廬江，朱然寇襄陽，皆無功而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-028-3', 'p0229', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '二年，吳大將全琮數萬衆寇芍陂，淩率諸軍逆討，與賊爭塘，力戰連日，賊退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-028-4', 'p0229', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初，吳大將全琮，孫權之婚親重臣也，琮子懌、孫靜、從子端、翩、緝等，皆將兵來救誕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-037-5', 'p0229', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '及當西還，並會昌門，陸績、顧劭、全琮皆往。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-037-6', 'p0229', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '謂全琮曰：「卿好施慕名，有似汝南樊子昭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-7', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '近得守將周泰、全琮等白事，過月六日，有馬步七百，徑到橫江，又督將馬和復將四百人進到居巢，琮等聞有兵馬渡江，視之，為兵馬所擊，臨時交鋒，大相殺傷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-8', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '將軍全琮、徐盛追斬魏將尹盧，殺獲數百。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-9', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '衞將軍全琮表稱熾任大將軍，赴召，道卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-10', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '以全琮為太守，平討山越。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-11', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '是歲，權向合肥新城，遣將軍全琮征六安，皆不克還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-12', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十月，遣衞將軍全琮襲六安，不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-13', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '夏四月，遣衞將軍全琮略淮南，決芍陂，燒安城邸閣，收其人民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-14', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，以驃騎步隲為丞相，車騎朱然為左大司馬，衞將軍全琮為右大司馬，鎮南呂岱為上大將軍，威北將軍諸葛恪為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-15', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十年春正月，右大司馬全琮卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-050-16', 'p0229', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '生二女，長曰魯班，字大虎，前配周瑜子循，後配全琮；少曰魯育，字小虎，前配朱據，後配劉纂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-052-17', 'p0229', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '時長公主壻衞將軍全琮子寄為霸賔客，寄素傾邪，譚所不納。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-052-18', 'p0229', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '先是，譚弟承與張休俱北征壽春，全琮時為大都督，與魏將王淩戰於芍陂，軍不利，魏兵乘勝陷沒五營將秦晃軍，休、承奮擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-052-19', 'p0229', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '吳錄曰：全琮父子屢言芍陂之役為典軍陳恂詐增張休、顧承之功，而休、承與恂通情。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-054-20', 'p0229', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」瑾、隲表比上，朱然及全琮亦俱陳乞，權乃許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-054-21', 'p0229', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '峻卒，全琮表峻子護為將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-055-22', 'p0229', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '曹休出洞口，盛與呂範、全琮渡江拒守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-056-23', 'p0229', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '嘉禾三年，權與蜀克期大舉，權自向新城，然與全琮各受斧鉞，為左右督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-056-24', 'p0229', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '曹休、張遼、臧霸等來伐，範督徐盛、全琮、孫韶等，以舟師拒休等於洞口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-056-25', 'p0229', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '性好威儀，州民如陸遜、全琮及貴公子，皆脩敬虔肅，不敢輕脫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-056-26', 'p0229', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '時陸遜為元帥，全琮與桓為左右督，各督三萬人擊休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-056-27', 'p0229', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '桓與衞將軍全琮俱以師迎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-056-28', 'p0229', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '是時全琮為督，權又令偏將軍胡綜宣傳詔命，參與軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-057-29', 'p0229', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」大司農劉基曰：「可與全琮為輩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-058-30', 'p0229', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '遜自為中部，令朱桓、全琮為左右翼，三道俱進，果衝休伏兵，因驅走之，追亡逐北，徑至夾石，斬獲萬餘，牛馬騾驢車乘萬兩，軍資器械略盡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-058-31', 'p0229', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '全琮報遜，遜以為子弟苟有才，不憂不用，不宜私出以要榮利；若其不佳，終為取禍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-059-32', 'p0229', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '時廷尉監隱蕃交結豪傑，自衞將軍全琮等皆傾心敬待，惟衜及宣詔郎豫章楊迪拒絕不與通，時人咸怪之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-059-33', 'p0229', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-059-34', 'p0229', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-059-35', 'p0229', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '呂岱、全琮之徒，蓋所不足論耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-060-36', 'p0229', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '全琮字子璜，吳郡錢唐人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-060-37', 'p0229', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂範、孫韶等入淮，全琮、朱桓趨合肥，諸葛瑾、步隲、朱然到襄陽，陸議、潘璋等討梅敷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-060-38', 'p0229', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂岱清恪在公；周魴譎略多奇；鍾離牧蹈長者之規；全琮有當世之才，貴重於時，然不檢姧子，獲譏毀名云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a05-001-39', 'p0229', 'jinshu', 'a05-001', '《晉書·卷一》', '二年夏五月，吳將全琮寇芍陂，朱然、孫倫圍樊城，諸葛瑾、步騭掠柤中，帝請自討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a05-002-40', 'p0229', 'jinshu', 'a05-002', '《晉書·卷二》', '奇兵震擊，而朱異摧破；神變應機，而全琮稽服；取亂攻昧，而高墉不守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-047-0', 'p0230', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '四年夏，遣呂岱討桓等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-047-1', 'p0230', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '夏，呂岱討廬陵賊，畢，還陸口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-047-2', 'p0230', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '禮還，復有詔責數諸葛瑾、步隲、朱然、呂岱等曰：「袁禮還，云與子瑜、子山、義封、定公相見，並以時事當有所先後，各自以不掌民事，不肯便有所陳，悉推之伯言、承明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-047-3', 'p0230', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '遣將軍呂岱、唐咨討之，歲餘皆破。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-047-4', 'p0230', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，以驃騎步隲為丞相，車騎朱然為左大司馬，衞將軍全琮為右大司馬，鎮南呂岱為上大將軍，威北將軍諸葛恪為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-048-5', 'p0230', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '閏月，以恪為帝太傅，胤為衞將軍領尚書事，上大將軍呂岱為大司馬，諸文武在位皆進爵班賞，宂官加等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-048-6', 'p0230', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '癸卯，更以胤為大司馬，代呂岱駐武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-048-7', 'p0230', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-049-8', 'p0230', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '權以交阯縣遠，乃分合浦以北為廣州，呂岱為刺史；交阯以南為交州，戴良為刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-049-9', 'p0230', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '而呂岱被詔誅徽，自廣州將兵晝夜馳入，過合浦，與良俱前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-049-10', 'p0230', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '呂岱師友士匡，使通信誓，徽兄弟肉袒，推心委命，岱因滅之，以要功利，君子是以知孫權之不能遠略，而呂氏之祚不延者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-052-11', 'p0230', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '延康元年，權遣呂岱代隲，隲將交州義士萬人出長沙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-053-12', 'p0230', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '時交土始開，刺吏呂岱率師討伐，綜與俱行，越海南征，及到九真。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-053-13', 'p0230', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '呂岱從交州召出，綜懼繼岱者非其人，上疏曰：「昔帝舜南巡，卒於蒼梧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-053-14', 'p0230', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '呂岱旣至，有士民之變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-057-15', 'p0230', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '欲諫不敢，作表以示呂岱，岱不報，為愛憎所白，復徙蒼梧猛陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-057-16', 'p0230', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」粲募合人衆，拜昭義中郎將，與呂岱討平山越，入為屯騎校尉、少府，遷太子太傅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-059-17', 'p0230', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-059-18', 'p0230', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-059-19', 'p0230', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '呂岱、全琮之徒，蓋所不足論耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-059-20', 'p0230', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '大司馬呂岱親受先帝詔勑，輔導大王，旣不承用其言，令懷憂怖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-060-21', 'p0230', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂岱字定公，廣陵海陵人也，為郡縣吏，避亂南渡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-060-22', 'p0230', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '權聞之歎息，以讓羣臣曰：「呂岱出身萬里，為國勤事，家門內困，而孤不早知。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-060-23', 'p0230', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '」及原死，岱哭之甚哀，曰：「德淵，呂岱之益友，今不幸，岱復於何聞過？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-060-24', 'p0230', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂岱清恪在公；周魴譎略多奇；鍾離牧蹈長者之規；全琮有當世之才，貴重於時，然不檢姧子，獲譏毀名云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-063-25', 'p0230', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '」後呂岱從蜀還，遇之白帝，說備部衆離落，死亡且半，事必不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-064-26', 'p0230', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '臨去，大司馬呂岱戒之曰：「世方多難，子每事必十思。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-064-27', 'p0230', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '呂據聞之大恐，與諸督將連名，共表薦滕胤為丞相，綝更以胤為大司馬，代呂岱駐武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a05-015-28', 'p0230', 'jinshu', 'a05-015', '《晉書·卷十五》', '戴良為刺史，值亂不得入，呂岱擊平之，復還并交部。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0231-a04-047-0', 'p0231', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '夏五月，鄱陽太守周魴偽叛，誘魏將曹休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0231-a04-056-1', 'p0231', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '黃武七年，鄱陽太守周魴譎誘魏大司馬曹休，休將步騎十萬至皖城以迎魴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0231-a04-058-2', 'p0231', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '七年，權使鄱陽太守周魴譎魏大司馬曹休，休果舉衆入皖，乃召遜假黃鉞，為大都督，逆休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0231-a04-060-3', 'p0231', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '周魴字子魚，吳郡陽羨人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0231-a04-060-4', 'p0231', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂岱清恪在公；周魴譎略多奇；鍾離牧蹈長者之規；全琮有當世之才，貴重於時，然不檢姧子，獲譏毀名云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0232-a04-048-0', 'p0232', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '鄱陽、新都民為亂，廷尉丁密、步兵校尉鄭胄、將軍鍾離牧率軍討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0232-a04-060-1', 'p0232', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '鍾離牧字子幹，會稽山陰人，漢魯相意七世孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0232-a04-060-2', 'p0232', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂岱清恪在公；周魴譎略多奇；鍾離牧蹈長者之規；全琮有當世之才，貴重於時，然不檢姧子，獲譏毀名云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a03-112-0', 'p0233', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '三國時陸遜攻襄陽，又值此穴中有數十匹馬出，遜載還建業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-026-1', 'p0233', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '明年，吴將陸遜向廬江，論者以為宜速赴之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-027-2', 'p0233', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '今陸遜等已死，而權年老，內無賢嗣，中無謀主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-039-3', 'p0233', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '臣松之以為陳羣子泰，陸遜子抗，傳皆以子繫父，不別載姓，及王肅、杜恕、張承、顧劭之流，莫不皆然，惟董允獨否，未詳其意，當以允名位優重，事跡踰父故邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-4', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '陸遜別取宜都，獲秭歸、枝江、夷道，還屯夷陵，守峽口以備蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-5', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權以陸遜為督，督朱然、潘璋等以拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-6', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '黃武元年春正月，陸遜部將軍宋謙等攻蜀五屯，皆破之，斬其將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-7', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權未之許，而謂將相曰：「往年孤以玄德方向西鄙，故先命陸遜選衆以待之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-8', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」是時陸遜以所在少穀，表令諸將增廣農畒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-9', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十月，陸遜陳便宜，勸以施德緩刑，寬賦息調。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-10', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋八月，權至皖口，使將軍陸遜督諸將大破休於石亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-11', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」秋九月，權遷都建業，因故府不改館，徵上大將軍陸遜輔太子登，掌武昌留事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-12', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」夏五月，權遣陸遜、諸葛瑾等屯江夏、沔口，孫韶、張承等向廣陵、淮陽，權率大衆圍合肥新城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-13', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '陸遜陳其素行，因為之請，權乃減宗一等，後不得以為比，因此遂絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-14', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '二月，陸遜討彭旦等，其年，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-15', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '陛下身自御戎，取亂侮亡，宜滌荊、揚之地，舉彊羸之數，使彊者執戟，羸者轉運，西命益州軍于隴右，授諸葛瑾、朱然大衆指事襄陽，陸遜、朱桓別征壽春，大駕入淮陽，歷青、徐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-16', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '七年春正月，以上大將軍陸遜為丞相。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-17', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '八年春二月，丞相陸遜卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-051-18', 'p0233', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '鎮巴丘，數咨陸遜以得失。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-051-19', 'p0233', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '年二十五，拜安東中郎將，與陸遜共拒劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-20', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '壹姦險亂法，毀傷忠賢，吳國寒心，自太子登、陸遜已下，切諫不能得，是以潘濬欲因會同手劒之，以除國患，疾惡忠主，義形於色，而今乃發起令言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-21', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '少與舅陸績齊名，而陸遜、張敦、卜靜等皆亞焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-22', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '此語頗流聞於外，陸遜表保明瑾無此，宜以散其意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-23', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '是歲，都督西陵，代陸遜撫二境，頃以兾州在蜀分，解牧職。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-24', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」隲於是條于時事業在荊州界者，諸葛瑾、陸遜、朱然、程普、潘濬、裴玄、夏侯承、衞旌、李肅、吳書曰：肅字偉恭，南陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-25', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '自今蔽獄，都下則宜諮顧雍，武昌則陸遜、潘濬，平心專意，務在得情，隲黨神明，受罪何恨？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-26', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」又曰：「丞相顧雍、上大將軍陸遜、太常潘濬，憂深責重，志在謁誠，夙夜兢兢，寢食不寧，念欲安國利民，建乆長之計，可謂心膂股肱，社稷之臣矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-27', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '赤烏九年，代陸遜為丞相，猶誨育門生，手不釋書，被服居處有如儒生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-053-28', 'p0233', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '權為吳王，拜固議郎，自陸遜、張溫、駱統等皆拜之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-054-29', 'p0233', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫權與陸遜論周瑜、魯肅及蒙曰：「公瑾雄烈，膽略兼人，遂破孟德，開拓荊州，邈焉難繼，君今繼之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-055-30', 'p0233', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '宜都之役，與陸遜、朱然等共攻蜀軍於涿鄉，大破之，徙威烈將軍，封都亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-055-31', 'p0233', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '陸遜拜表偏將軍，進封都鄉侯，北屯章阬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-055-32', 'p0233', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '劉備出夷陵，璋與陸遜并力拒之，璋部下斬備護軍馮習等，所殺傷甚衆，拜平北將軍、襄陽太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-055-33', 'p0233', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '少以驍勇為小將，屬甘寧、陸遜、潘璋等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-056-34', 'p0233', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '黃武元年，劉備舉兵攻宜都，然督五千人與陸遜并力拒備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-056-35', 'p0233', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '又陸遜亦卒，功臣名將存者惟然，莫與比隆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-056-36', 'p0233', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '性好威儀，州民如陸遜、全琮及貴公子，皆脩敬虔肅，不敢輕脫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-056-37', 'p0233', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '時陸遜為元帥，全琮與桓為左右督，各督三萬人擊休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-056-38', 'p0233', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '」權先與陸遜議，遜以為不可，故計不施行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-057-39', 'p0233', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '以隨陸遜破蜀軍於宜都，遷偏將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-057-40', 'p0233', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '雖起孤微，與同郡陸遜、卜靜等比肩齊聲矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-057-41', 'p0233', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '又數以消息語陸遜，遜時駐武昌，連表諫爭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-058-42', 'p0233', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '陸遜字伯言，吳郡吳人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-058-43', 'p0233', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '」蒙對曰：「陸遜意思深長，才堪負重，觀其規慮，終可大任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-058-44', 'p0233', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '評曰：劉備天下稱雄，一世所憚，陸遜春秋方壯，威名未著，摧而克之，罔不如志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-059-45', 'p0233', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '權遷都建業，徵上大將軍陸遜輔登鎮武昌，領宮府留事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-059-46', 'p0233', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '住十餘日，欲遣西還，深自陳乞，以乆離定省，子道有闕，又陳陸遜忠勤，無所顧憂，權遂留焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-059-47', 'p0233', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '陸遜忠勤於時，出身憂國，謇謇在公，有匪躬之節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-059-48', 'p0233', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '魯王霸覬覦滋甚，陸遜、吾粲、顧譚等數陳適庶之義，理不可奪，全寄、楊笁為魯王霸支黨，譖愬日興。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-059-49', 'p0233', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-060-50', 'p0233', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '齊與陸遜討破突，斬首數千，餘黨震服，丹楊三縣皆降，料得精兵八千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-060-51', 'p0233', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '七年，權到皖，使琮與輔國將軍陸遜擊曹休，破之於石亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-060-52', 'p0233', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '潘濬卒，岱代濬領荊州文書，與陸遜並在武昌，故督蒲圻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-060-53', 'p0233', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '」及陸遜卒，諸葛恪代遜，權乃分武昌為兩部，岱督右部，自武昌上至蒲圻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-060-54', 'p0233', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '魴亦合衆，隨陸遜橫截休，休幅裂瓦解，斬獲萬計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-060-55', 'p0233', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '嗣弟怖懼，詣武昌降於陸遜，乞出平地，自改為善，由是數郡無復憂惕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-061-56', 'p0233', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '先是，濬與陸遜俱駐武昌，共掌留事，還復故。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-061-57', 'p0233', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '太子不見，而微服至其車上，與共密議，欲令陸遜表諫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-064-58', 'p0233', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '諸葛亮聞恪代詳，書與陸遜曰：「家兄年老，而恪性踈，今使典主糧穀，糧穀軍之要最，僕雖在遠，竊用不安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-064-59', 'p0233', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '與丞相陸遜書曰：「楊敬叔傳述清論，以為方今人物彫盡，守德業者不能復幾，宜相左右，更為輔車，上熙國事，下相珍惜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-064-60', 'p0233', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '若躬行所與陸遜及弟融之書，則悔吝不至，何尤禍之有哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-041-0', 'p0234', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '孫休怒，復遣陸抗等帥衆三萬人增憲之圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-048-1', 'p0234', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '二月，鎮軍陸抗、撫軍步恊、征西將軍留平、建平太守盛曼，率衆圍蜀巴東守將羅憲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-048-2', 'p0234', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '魏使將軍胡烈步騎二萬侵西陵，以救羅憲，陸抗等引軍退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-048-3', 'p0234', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '遣樂鄉都督陸抗圍取闡，闡衆悉降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-048-4', 'p0234', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '二年春三月，以陸抗為大司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-048-5', 'p0234', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '陸抗之克步闡，皓意張大，乃使尚廣筮并天下，遇同人之頤，對曰：「吉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-052-6', 'p0234', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫皓使陸抗西行，祜等遁退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-056-7', 'p0234', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '吳書曰：綝要異相見，將往，恐陸抗止之，異曰：「子通，家人耳，當何所疑乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-058-8', 'p0234', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '陸抗每告其邊戍曰：「彼專為德，我專為暴，是不戰而自服也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-061-9', 'p0234', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '初，皓常銜凱數犯顏忤旨，加何定譖構非一，旣以重臣，難繩以法，又陸抗時為大將在疆埸，故以計容忍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-065-10', 'p0234', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '定聞陸抗表至，成都不守，臣主播越，社稷傾覆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a05-003-11', 'p0234', 'jinshu', 'a05-003', '《晉書·卷三》', '吳將陸抗攻闡，遣車騎將軍羊祜帥衆出江陵，荊州刺史楊肇迎闡於西陵，巴東監軍徐胤擊建平以救闡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a05-034-12', 'p0234', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '吳將陸抗攻之甚急，詔祜迎闡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a05-034-13', 'p0234', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '祜與陸抗相對，使命交通，抗稱祜之德量，雖樂毅、諸葛孔明不能過也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a04-037-0', 'p0235', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '及當西還，並會昌門，陸績、顧劭、全琮皆往。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a04-048-1', 'p0235', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a04-052-2', 'p0235', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '少與舅陸績齊名，而陸遜、張敦、卜靜等皆亞焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a04-057-3', 'p0235', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '陸績字公紀，吳郡吳人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a04-057-4', 'p0235', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '豫自知亡日，乃為辭曰：「有漢志士吳郡陸績，幼敦詩、書，長玩禮、易，受命南征，遘疾遇厄，遭命不幸，嗚呼悲隔！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a04-057-5', 'p0235', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '臣切見故鬱林太守陸績女子鬱生，少履貞特之行，幼立匪石之節，年始十三，適同郡張白。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a04-057-6', 'p0235', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '陸績之於楊玄，是仲尼之左丘明，老聃之嚴周矣；以瑚璉之器，而作守南越，不亦賊夫人歟！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a05-011-7', 'p0235', 'jinshu', 'a05-011', '《晉書·卷十一》', '」陸績云：「天東西南北徑三十五萬七千里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a05-011-8', 'p0235', 'jinshu', 'a05-011', '《晉書·卷十一》', '而陸績造渾象，其形如鳥卵，然則黃道應長於赤道矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-013-0', 'p0236', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '胡冲吳歷曰：孫策擊豫章，先遣虞翻說歆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-013-1', 'p0236', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '虞溥江表傳曰：孫策在椒丘，遣虞翻說歆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-013-2', 'p0236', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '朗功曹虞翻以為力不能拒，不如避之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-048-3', 'p0236', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-049-4', 'p0236', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '權嘗宴飲，騎都尉虞翻醉酒犯忤，權欲殺之，威怒甚盛，由基諫爭，翻以得免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-052-5', 'p0236', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '虞翻以狂直流徙，惟瑾屢為之說。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-054-6', 'p0236', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '吳書曰：將軍士仁在公安拒守，蒙令虞翻說之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-057-7', 'p0236', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '虞翻字仲翔，會稽餘姚人也，吳書曰：翻少好學，有高氣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-057-8', 'p0236', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」權曰：「曹孟德尚殺孔文舉，孤於虞翻何有哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-057-9', 'p0236', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '虞翻亮直，善於盡言，國之周舍也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-057-10', 'p0236', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '昔初平末年，王府君以淵妙之才，超遷臨郡，思賢嘉善，樂采名俊，問功曹虞翻曰：『聞玉出崑山，珠生南海，遠方異域，各生珍寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-057-11', 'p0236', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '其聦明大略，忠直謇諤，則侍御史餘姚虞翻、偏將軍烏傷駱統。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-057-12', 'p0236', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '虞翻舊齒名盛，龐統荊州令士，年亦差長，皆與績友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-057-13', 'p0236', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '評曰：虞翻古之狂直，固難免乎末世，然權不能容，非曠宇也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-059-14', 'p0236', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '蔣脩、虞翻，志節分明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-064-15', 'p0236', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '虞翻徙交州，縣令使友送之，翻與語而奇焉，為書與豫章太守謝斐，令以為功曹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-full-0', 'p0237', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '司空張濟罷，大司農張溫為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-full-1', 'p0237', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '八月，以司空張溫為車騎將軍，討北宮伯玉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-full-2', 'p0237', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '十一月，張溫破北宮伯玉於美陽，因遣盪寇將軍周慎追擊之，圍榆中；縣名，故城在今蘭州金城縣東也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-full-3', 'p0237', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '車騎將軍張溫為太尉，中常侍趙忠為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-full-4', 'p0237', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '太尉張溫免，司徒崔烈為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-5', 'p0237', 'houhanshu', 'a03-008', '《後漢書·卷八》', '司空張濟罷，大司農張溫為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-6', 'p0237', 'houhanshu', 'a03-008', '《後漢書·卷八》', '八月，以司空張溫為車騎將軍，討北宮伯玉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-7', 'p0237', 'houhanshu', 'a03-008', '《後漢書·卷八》', '十一月，張溫破北宮伯玉於美陽，因遣盪寇將軍周慎追擊之，圍榆中；縣名，故城在今蘭州金城縣東也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-8', 'p0237', 'houhanshu', 'a03-008', '《後漢書·卷八》', '車騎將軍張溫為太尉，中常侍趙忠為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-9', 'p0237', 'houhanshu', 'a03-008', '《後漢書·卷八》', '太尉張溫免，司徒崔烈為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-009-10', 'p0237', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十月壬戌，董卓殺衞尉張溫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-036-11', 'p0237', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '司空張溫數以禮辟，不能致。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-038-12', 'p0237', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '後尚書令張溫特表薦之，徵拜尚書僕射。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-052-13', 'p0237', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '是時段熲、樊陵、張溫等雖有功勤名譽，然皆先輸貨財而後登公位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-054-14', 'p0237', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '二年九月，復代張溫為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-057-15', 'p0237', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '將軍張溫天性精勇，而主者旦夕迫促，軍無後殿，假令失利，其敗不救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-058-16', 'p0237', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '」虞、紹亦素有謀，因相連結，未及發，而司隷校尉張溫舉勳為京兆尹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-064-17', 'p0237', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '車騎將軍張溫西征關中，請補長史，別屯安定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-071-18', 'p0237', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '司空張溫上疏曰：「昔秦用白起，燕任樂毅，皆曠年歷載，乃能克敵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-072-19', 'p0237', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '朝廷復以司空張溫為車騎將軍，假節，執金吾袁滂為副。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-072-20', 'p0237', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '三年春，遣使者持節就長安拜張溫為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-072-21', 'p0237', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓乃使人誣衞尉張溫與袁術交通，遂笞溫於市，殺之，以塞天變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-073-22', 'p0237', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '後車騎將軍張溫討賊邊章等，發幽州烏桓三千突騎，而牢稟逋懸，前書音義曰：「牢，賈直也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-073-23', 'p0237', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '中平中，以瓚督烏桓突騎，車騎將軍張溫討涼州賊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-073-24', 'p0237', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '』」四遷為車騎將軍張溫司馬，西討邊章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-078-25', 'p0237', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '其所進達，皆海內名人，陳留虞放、邊韶、南陽延固、張溫、弘農張奐、潁川堂谿典等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-083-26', 'p0237', 'houhanshu', 'a03-083', '《後漢書·卷八十三》', '尚書郎南陽張溫異之，使問曰：「人皆來觀，老父獨不輟，何也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-001-27', 'p0237', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '其所稱薦，若陳留虞放、邊韶、南陽延固、張溫、弘農張奐、潁川堂谿典等，皆致位公卿，而不伐其善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-006-28', 'p0237', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '故太尉張溫時為衞尉，素不善卓，卓心怨之，因天有變，欲以塞咎，使人言溫與袁術交關，遂笞殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-006-29', 'p0237', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '傅子曰：靈帝時牓門賣官，於是太尉段熲、司徒崔烈、太尉樊陵、司空張溫之徒，皆入錢上千萬下五百萬以買三公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-008-30', 'p0237', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '遷幽州刺史，徵拜議郎，參車騎將軍張溫軍事，西討韓遂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-008-31', 'p0237', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '後邊章、韓遂為亂，司空張溫銜命征討；又請謙為參軍事，接遇甚厚，而謙輕其行事，心懷不服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-038-32', 'p0237', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '吳遣使張溫來聘，百官皆往餞焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-045-33', 'p0237', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '」遂自絕魏，與蜀連和，遣張溫報聘於蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-046-34', 'p0237', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '中平三年，遣司空張溫行車騎將軍，西討章等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-046-35', 'p0237', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '孤語張溫，求引所將兵為慎作後駐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-047-36', 'p0237', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '三年夏，遣輔義中郎將張溫聘于蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-047-37', 'p0237', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '張溫、曁豔奏其事，邵辭位請罪，權釋令復職，年六十三卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-048-38', 'p0237', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-050-39', 'p0237', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '奮弟祺，吳書曰：祺與張溫、顧譚友善，權令關平辭訟事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-052-40', 'p0237', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '後與張溫俱使蜀，諸葛亮甚稱歎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-053-41', 'p0237', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '權為吳王，拜固議郎，自陸遜、張溫、駱統等皆拜之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-057-42', 'p0237', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '績於鬱林所生女，名曰鬱生，適張溫弟白。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-057-43', 'p0237', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '張溫字惠恕，吳郡吳人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-057-44', 'p0237', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '權幽之有司，下令曰：「昔令召張溫，虛己待之，旣至顯授，有過舊臣，何圖凶醜，專挾異心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-057-45', 'p0237', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '多士旣受普篤之恩，張溫又蒙最隆之施。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-057-46', 'p0237', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」　臣松之以為莊周云「名者公器也，不可以多取」，張溫之廢，豈其取名之多乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-057-47', 'p0237', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '權咨嗟將率，發憤歎息，追思呂蒙、張溫，以為據才兼文武，可以繼之，自是拜建義校尉，領兵屯湖孰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-057-48', 'p0237', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '張溫才藻俊茂，而智防未備，用致艱患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-059-49', 'p0237', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '太傅張溫言於權曰：「夫中庶子官最親密，切問近對，宜用儁德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-063-50', 'p0237', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '于時吳使張溫先在蜀，旣於市中相識，甚驚，便作書寄其家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-064-51', 'p0237', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '時皇象亦寓居山陰，吳郡張溫來就象學，欲得所舍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-048-0', 'p0238', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-053-1', 'p0238', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '權為吳王，拜固議郎，自陸遜、張溫、駱統等皆拜之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-057-2', 'p0238', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '陵卒，僮客土田或見侵奪，駱統為陵家訟之，求與丁覽、卜清等為比，權許焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-057-3', 'p0238', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '其聦明大略，忠直謇諤，則侍御史餘姚虞翻、偏將軍烏傷駱統。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-057-4', 'p0238', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '將軍駱統表理溫曰：「伏惟殿下，天生明德，神啟聖心，招髦秀於四方，置俊乂於宮朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-057-5', 'p0238', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '權旣疾溫名盛，而駱統方驟言其美，至云「卓躒冠羣，煒曄曜世，世人未有及之者也」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-057-6', 'p0238', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '駱統字公緒，會稽烏傷人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-057-7', 'p0238', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '駱統抗明大義，辭切理至，值權方閉不開。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-058-8', 'p0238', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '權以問遜，遜與朱然、駱統以為曹丕大合士衆，外託助國討備，內實有姦心，謹決計輒還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-058-9', 'p0238', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '駱統子名秀，被門庭之謗，衆論狐疑，莫能證明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0239-a04-052-0', 'p0239', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '承字子直，嘉禾中與舅陸瑁俱以禮徵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0239-a04-057-1', 'p0239', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '陸瑁字子璋，丞相遜弟也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0239-a04-057-2', 'p0239', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '陸瑁篤義規諫，君子有稱焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-047-0', 'p0240', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '中郎將吾粲獲李桓，將軍唐咨獲羅厲等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-052-1', 'p0240', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '昔丁諝出於孤家，吾粲由於牧豎，豫章揚其善，以並陸、全之列，是以人無幽滯而風俗厚焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-057-2', 'p0240', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '吾粲字孔休，吳郡烏程人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-057-3', 'p0240', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '吾粲、朱據遭罹屯蹇，以正喪身，悲夫！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-058-4', 'p0240', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '太子太傅吾粲坐數與遜交書，下獄死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-059-5', 'p0240', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-059-6', 'p0240', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '魯王霸覬覦滋甚，陸遜、吾粲、顧譚等數陳適庶之義，理不可奪，全寄、楊笁為魯王霸支黨，譖愬日興。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-060-7', 'p0240', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '吾粲、唐咨甞以三千兵攻守，連月不能拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-045-0', 'p0241', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '－－贊糜芳、士仁、郝普、潘濬糜芳字子方，東海人也，為南郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-045-1', 'p0241', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '潘濬字承明，武陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-047-2', 'p0241', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '三年春二月，遣太常潘濬率衆五萬討武陵蠻夷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-047-3', 'p0241', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十一月，太常潘濬平武陵蠻夷，事畢，還武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-047-4', 'p0241', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權大怒，召胄還，潘濬、陳表並為請，得釋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-048-5', 'p0241', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-048-6', 'p0241', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '拔呂蒙於戎行，識潘濬於係虜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-051-7', 'p0241', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '時太常潘濬掌荊州事，重安長陳留舒燮有罪下獄，濬嘗失燮，欲致之於法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-052-8', 'p0241', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '壹姦險亂法，毀傷忠賢，吳國寒心，自太子登、陸遜已下，切諫不能得，是以潘濬欲因會同手劒之，以除國患，疾惡忠主，義形於色，而今乃發起令言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-052-9', 'p0241', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」隲於是條于時事業在荊州界者，諸葛瑾、陸遜、朱然、程普、潘濬、裴玄、夏侯承、衞旌、李肅、吳書曰：肅字偉恭，南陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-052-10', 'p0241', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '自今蔽獄，都下則宜諮顧雍，武昌則陸遜、潘濬，平心專意，務在得情，隲黨神明，受罪何恨？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-052-11', 'p0241', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」又曰：「丞相顧雍、上大將軍陸遜、太常潘濬，憂深責重，志在謁誠，夙夜兢兢，寢食不寧，念欲安國利民，建乆長之計，可謂心膂股肱，社稷之臣矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-056-12', 'p0241', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '叔父才卒，績領其兵，隨太常潘濬討五溪，以膽力稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-056-13', 'p0241', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '隨太常潘濬討五谿，復有功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-058-14', 'p0241', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '時中書典校呂壹，竊弄權柄，擅作威福，遜與太常潘濬同心憂之，言至流涕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-060-15', 'p0241', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '會武陵蠻夷蠢動，岱與太常潘濬共討定之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-060-16', 'p0241', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '潘濬卒，岱代濬領荊州文書，與陸遜並在武昌，故督蒲圻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-060-17', 'p0241', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '其六曰：「東主致恨前者不拔石陽，今此後舉，大合新兵，并使潘濬發夷民，人數甚多，聞豫設科條，當以新羸兵置前，好兵在後，攻城之日，云欲以羸兵填壍，使即時破，雖未能然，是事大趣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-061-18', 'p0241', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '潘濬字承明，武陵漢壽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-061-19', 'p0241', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '評曰：潘濬公清割斷，陸凱忠壯質直，皆節槩梗梗，有大丈夫格業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-047-0', 'p0242', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋七月，遣將軍聶友、校尉陸凱以兵三萬討珠崖、儋耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-047-1', 'p0242', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十二月，魏大將軍王昶圍南郡，荊州刺史王基攻西陵，遣將軍戴烈、陸凱往拒之，皆引還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-048-2', 'p0242', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '」皓訪羣臣，鎮西大將軍陸凱曰：「夫兵不得已而用之耳，且三國鼎立已來，更相侵伐，無歲寧居。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-048-3', 'p0242', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '以陸凱為左丞相，常侍萬彧為右丞相。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-048-4', 'p0242', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '十一月，左丞相陸凱卒。');
